WITH with_windows AS (SELECT *, NTILE(10) OVER (PARTITION BY product_id ORDER BY revenue DESC, id) AS revenue_bucket, ROUND(revenue / SUM(revenue) OVER (PARTITION BY product_id), 4) AS revenue_share, FIRST_VALUE(units, TRUE) OVER (PARTITION BY product_id ORDER BY sale_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_units FROM store_sales) SELECT CASE WHEN units >= 44 THEN 'LARGE' ELSE 'SMALL' END AS units_tier, DATE_TRUNC('YEAR', sale_date) AS year_start, COUNT(DISTINCT store_id) AS distinct_store_ids, BIT_AND(units) AS units_bit_and, COUNT(*) AS event_count FROM with_windows GROUP BY ROLLUP (CASE WHEN units >= 44 THEN 'LARGE' ELSE 'SMALL' END, DATE_TRUNC('YEAR', sale_date)) HAVING distinct_store_ids > 1 ORDER BY distinct_store_ids;
